package org.apache.sysds.test.component.federated.placement.guard;
import java.nio.charset.StandardCharsets;import java.util.Base64;import java.util.Map;
/** Literal exact commitments: decoded values contain unique role identities and exact set/universe digests. */
final class R4Heuristic2LiteralExpectations {
 private static final Map<String,String> EXACT=Map.ofEntries(
  Map.entry("H-01-TWRITE-TREAD",""),
  Map.entry("H-02-BRANCH-JOIN",""),
  Map.entry("H-03-LOOP-RECOMPILE",""),
  Map.entry("H-04-FUNCTION-CALLSITE",""),
  Map.entry("H-05-CLONE-FAMILY",""),
  Map.entry("H-06-DYNAMIC-REWRITE",""),
  Map.entry("H-07-VARIABLE-REUSE",""),
  Map.entry("H-08-LATER-ANCHOR-NO-REFED",""),
  Map.entry("H-09-INDEPENDENT-ANCHOR-RELEASE",""),
  Map.entry("H-10-SAME-SHAPE-DISTINCT-ANCHORS","")
 );
 static String exact(String id){String x=EXACT.get(id);if(x==null)throw new AssertionError("MISSING_LITERAL_EXPECTATION|"+id);return new String(Base64.getDecoder().decode(x),StandardCharsets.UTF_8);}
 private R4Heuristic2LiteralExpectations(){}
}
